            while queue:
                x, y, path = queue.popleft()

                if len(path) == k:
                    if best_path is None or path < best_path:
                        best_path = path
                    continue

                for dx, dy in directions:
                    new_x, new_y = x + dx, y + dy
                    if is_within_bounds(new_x, new_y):
                        queue.append((new_x, new_y, path + [grid[new_x][new_y]]))

    return best_path

def tri(n):
    """Generate the first n + 1 numbers of the Tribonacci sequence."""
    def tribonacci_recursive(memo, n):
        if n in memo:
            return memo[n]
        if n == 1:
            result = 3
        elif n % 2 == 0:
            result = 1 + n / 2
        else:
            result = tribonacci_recursive(memo, n - 1) + tribonacci_recursive(memo, n - 2) + tribonacci_recursive(memo, n + 1)
        memo[n] = result
        return result

    memo = {}
    return [tribonacci_recursive(memo, i) for i in range(n + 1)]

