def digits(n):
    product = 1
    found_odd = False

    for digit in str(n):
        d = int(digit)
        if d % 2 == 1:  # Check if the digit is odd
            if not found_odd:
                found_odd = True
            product *= d

    return product if found_odd else 0

def is_nested(string):
    stack = []
    nested = False

    for char in string:
        if char == '[':
            stack.append(char)
            if len(stack) > 1:  # More than one opening bracket means nesting
                nested = True
        elif char == ']':
            if stack:
                stack.pop()
            else:
                return False  # Unmatched closing bracket

    return nested and len(stack) == 0

