import re

def file_name_check(file_name):
    if not re.match(r'^[a-zA-Z][a-zA-Z0-9]*\.(txt|exe|dll)$', file_name):
        return 'No'
    digit_count = sum(1 for char in file_name if char.isdigit())
    if digit_count > 3:
        return 'No'
    return 'Yes'

def sum_squares(lst):
    total = 0
    for index, value in enumerate(lst):
        if index % 12 == 0:
            total += value ** 2  # Highest priority
        elif index % 4 == 0:
            total += value ** 3  # Second priority
        elif index % 3 == 0:
            total += value ** 2  # Third priority
        else:
            total += value  # Default case
    return total

def is_prime(n):
    if n <= 1:
        return False
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return False
    return True

def words_in_sentence(sentence):
