def cycpattern_check(a, b):
    """Check if the second word or any of its rotations is a substring in the first word."""
    if len(b) == 0:
        return False

    # Create all rotations by concatenating b with itself
    b_double = b + b
    # Check for each rotation by slicing b_double
    for i in range(len(b)):
        if b_double[i:i + len(b)] in a:
            return True

    return False

def even_odd_count(num):
    """Given an integer. return a tuple that has the number of even and odd digits respectively."""
    num_str = str(abs(num))
    even_count = sum(1 for digit in num_str if int(digit) % 2 == 0)
    odd_count = sum(1 for digit in num_str if int(digit) % 2 != 0)
    return (even_count, odd_count)

def int_to_mini_roman(number):
    roman_numerals = [
        (1000, 'm'), (900, 'cm'), (500, 'd'), (400, 'cd'),
        (100, 'c'), (90, 'xc'), (50, 'l'), (40, 'xl'),
        (10, 'x'), (9, 'ix'), (5, 'v'), (4, 'iv'),
        (1, 'i')
    ]

    result = []
    for value, symbol in roman_numerals:
        while number >= value:
            result.append(symbol)
            number -= value

    return ''.join(result)

