def find_max(words):
    max_word = ""
    max_unique_count = 0

    for word in words:
        unique_char_count = len(set(word))

        if (unique_char_count > max_unique_count) or (unique_char_count == max_unique_count and word < max_word):
            max_unique_count = unique_char_count
            max_word = word

    return max_word

def do_algebra(operator, operand):
    if len(operator) != len(operand) - 1:
        raise ValueError("The number of operators must be one less than the number of operands.")

    # Validate operators
    valid_operators = {'+', '-', '*', '//', '**'}
    for op in operator:
        if op not in valid_operators:
            raise ValueError(f"Unsupported operator: {op}")

    # Build the expression as a string
    expression = str(operand[0])
    for op, val in zip(operator, operand[1:]):
        expression += f" {op} {val}"

    # Evaluate the expression safely
    try:
        result = eval(expression)
    except ZeroDivisionError:
        raise ValueError("Division by zero encountered in expression.")

    return result

